async function handle(job: Job) {
  try {
    const result = await provider.send(job.payload);
    await jobs.markComplete(job.id, result.id);
  } catch (error) {
    if (isTransient(error) && job.attempt < 3) {
      await queue.retry(job, 1000 * 2 ** job.attempt);
      return;
    }
    await queue.deadLetter(job, error);
  }
}
